#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <algorithm>
using namespace std;

int canon(const vector<long long>& par, map<vector<int>, int>& ids) {
    int n = (int)par.size();
    vector<vector<int>> kids(n + 1);
    int root = 0;
    for (int v = 1; v <= n; v++) {
        if (par[v - 1] == 0) root = v;
        else kids[par[v - 1]].push_back(v);
    }
    vector<int> order = {root};
    for (size_t i = 0; i < order.size(); i++) {
        for (int c : kids[order[i]]) order.push_back(c);
    }
    vector<int> ident(n + 1, 0);
    for (size_t i = order.size(); i-- > 0;) {
        int v = order[i];
        vector<int> key;
        for (int c : kids[v]) key.push_back(ident[c]);
        sort(key.begin(), key.end());
        if (!ids.count(key)) {
            int fresh = (int)ids.size();
            ids[key] = fresh;
        }
        ident[v] = ids[key];
    }
    return ident[root];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> p1(n);
    for (int i = 0; i < n; i++) cin >> p1[i];
    long long m;
    cin >> m;
    vector<long long> p2(m);
    for (int i = 0; i < m; i++) cin >> p2[i];

    map<vector<int>, int> ids;
    int first = canon(p1, ids);
    int second = canon(p2, ids);
    cout << (first == second ? "yes" : "no") << "\n";

    return 0;
}

